const { Kafka } = require('kafkajs');
const kafka = new Kafka({ clientId: 'ingest', brokers: ['kafka1:9092','kafka2:9092','kafka3:9092'] });
const producer = kafka.producer({ transactionalId: 'ingest-transaction' });
async function write(tenant, topic, messages) {
  const tx = await producer.transaction();
  try {
    for (const m of messages) {
      await tx.send({ topic: `${tenant}.${topic}`, messages: [ { key: m.key, value: m.value } ]});
    }
    await tx.commit();
  } catch (e) {
    await tx.abort();
    throw e;
  }
}
